#
# ======================================================================================
# Replaces the "Bench: <nodes>" line at the end of a PR description, or adds one if it doesn't have one.
# Other lines starting with "Bench:" (e.g. "Bench: 123 -> 456 nodes") are left alone.
#
# Usage: UpdateBenchLine.py <description file> <nodes>

import re
import sys
from pathlib import Path

BODY_FILE = Path(sys.argv[1])
NODES = int(sys.argv[2])

lines = BODY_FILE.read_text().replace("\r\n", "\n").rstrip().splitlines()

# drop any trailing "Bench: <nodes>" lines & the blank lines before them
while lines and (not lines[-1].strip() or re.fullmatch(r"Bench:\s*\d+\s*", lines[-1])):
    lines.pop()

lines += ["", f"Bench: {NODES}"] if lines else [f"Bench: {NODES}"]

BODY_FILE.write_text("\n".join(lines) + "\n")
